import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import './Home.css';

function Home() {
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.disconnect(); // Remove after first trigger
          }
        });
      },
      { threshold: 0.3 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section id="home" className="hero">
      <div className="container hero-inner">
        <div className="hero-copy">
          <h1>Your Space Can Now Listen, Learn and Respond!</h1>
          <p className="lead">Smart home & building automation solutions that make everyday living intelligent, efficient and secure.</p>
          <Link className="btn" to="/products">Our Products</Link>
        </div>
        <div className="hero-media">
          <img src="https://images.unsplash.com/photo-1506765515384-028b60a970df?q=80&w=1200&auto=format&fit=crop&ixlib=rb-4.0.3&s=placeholder" alt="Smart home"/>
        </div>
      </div>
    <section ref={sectionRef} className={`features fade-in-section ${isVisible ? 'visible' : ''}`}>
      <div className="feature-block">
        <div className="text">
          <h2>Innovative Solutions</h2>
          <p>
            At Kilowatt Electric, we specialize in smart home and building automation solutions designed to make everyday living more intelligent, efficient, and secure...
          </p>
        </div>
        <img src="data:image/webp;base64," alt="Modern Kitchen" />
      </div>

      <div className="feature-block reverse">
        <img src="https://via.placeholder.com/400x300" alt="Dining Room" />
        <div className="text">
          <h2>Seamless Integration</h2>
          <p>
            Whether it’s a private home, commercial space, hotel, or healthcare facility, we customize each solution to suit your unique needs...
          </p>
        </div>
      </div>
    </section>
    </section>
  );
}
export default Home;
